CREATE DATABASE IF NOT EXISTS mahavir_store CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE mahavir_store;
CREATE TABLE IF NOT EXISTS users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120) NOT NULL,email VARCHAR(190) NOT NULL UNIQUE,phone VARCHAR(20) DEFAULT NULL,password VARCHAR(255) NOT NULL,role ENUM('admin','customer') NOT NULL DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS categories(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE IF NOT EXISTS products(id INT AUTO_INCREMENT PRIMARY KEY,category_id INT NULL,name VARCHAR(160) NOT NULL,description TEXT,price DECIMAL(10,2) NOT NULL DEFAULT 0,stock INT NOT NULL DEFAULT 0,image VARCHAR(500) DEFAULT NULL,active TINYINT(1) NOT NULL DEFAULT 1,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(category_id) REFERENCES categories(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS orders(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NULL,customer_name VARCHAR(120) NOT NULL,phone VARCHAR(20) NOT NULL,address TEXT NOT NULL,total DECIMAL(10,2) NOT NULL,status ENUM('Pending','Processing','Delivered','Cancelled') NOT NULL DEFAULT 'Pending',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS order_items(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT NOT NULL,product_id INT NULL,product_name VARCHAR(160) NOT NULL,quantity INT NOT NULL,price DECIMAL(10,2) NOT NULL,FOREIGN KEY(order_id) REFERENCES orders(id) ON DELETE CASCADE,FOREIGN KEY(product_id) REFERENCES products(id) ON DELETE SET NULL);
CREATE TABLE IF NOT EXISTS settings(setting_key VARCHAR(100) PRIMARY KEY,setting_value TEXT);
INSERT IGNORE INTO categories(name) VALUES ('Vegetables'),('Fruits'),('Dairy'),('Staples'),('Snacks'),('Beverages'),('Personal Care');
INSERT INTO products(category_id,name,description,price,stock) SELECT c.id,'Fresh Tomatoes','Fresh local tomatoes',32,30 FROM categories c WHERE c.name='Vegetables' AND NOT EXISTS(SELECT 1 FROM products);
INSERT INTO products(category_id,name,description,price,stock) SELECT c.id,'Farm Fresh Milk','500 ml milk pack',30,40 FROM categories c WHERE c.name='Dairy' AND NOT EXISTS(SELECT 1 FROM products WHERE name='Farm Fresh Milk');
INSERT INTO products(category_id,name,description,price,stock) SELECT c.id,'Premium Basmati Rice','Premium rice per kg',120,25 FROM categories c WHERE c.name='Staples' AND NOT EXISTS(SELECT 1 FROM products WHERE name='Premium Basmati Rice');
